previewCss:
.darma-loader-magnifier-search {
  position: relative;
  width: 52px;
  height: 52px;
}
.darma-loader-magnifier-search i {
  position: absolute;
  top: 6px;
  left: 6px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 4px solid var(--loader-color, #6366f1);
  box-sizing: border-box;
  animation: darma-loader-magnifier-search-scan 2s ease-in-out infinite;
}
.darma-loader-magnifier-search i::after {
  content: "";
  position: absolute;
  bottom: -9px;
  right: -3px;
  width: 4px;
  height: 12px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
  transform: rotate(-45deg);
}
@keyframes darma-loader-magnifier-search-scan {
  0%, 100% { transform: translate(0, 0); }
  25% { transform: translate(20px, 2px); }
  50% { transform: translate(18px, 20px); }
  75% { transform: translate(2px, 18px); }
}

